#!/bin/sh
# Scaffold for scout-before-edit: writes the task's files into the current directory.
set -e
mkdir -p docs src/jobs src/net tests && printf 'RETRY_LIMIT = 3\nTIMEOUT_SECONDS = 30\n' > src/net/config.py && printf 'from net.config import RETRY_LIMIT\n\n\ndef fetch(url):\n    for attempt in range(RETRY_LIMIT):\n        pass\n' > src/net/client.py && printf 'from net.config import RETRY_LIMIT\n\n\ndef upload(path):\n    for attempt in range(RETRY_LIMIT):\n        pass\n' > src/net/upload.py && printf 'from net.config import RETRY_LIMIT\n\n\ndef run(job):\n    attempts = 0\n    while attempts < RETRY_LIMIT:\n        attempts += 1\n' > src/jobs/worker.py && printf 'WORKERS = 3\n\n\ndef plan(jobs):\n    return jobs[:WORKERS]\n' > src/jobs/scheduler.py && printf 'from net.config import RETRY_LIMIT\n\n\ndef test_retry_limit():\n    assert RETRY_LIMIT == 3\n' > tests/test_client.py && printf 'def test_worker_gives_up():\n    attempts_before_giving_up = 3\n    assert attempts_before_giving_up == 3\n' > tests/test_worker.py && printf '# Usage\n\nA failed request is retried up to 3 times.\nThe scheduler runs 3 workers at once.\n' > docs/usage.md && printf '# fixture project\n\nSee docs/usage.md.\n' > README.md
